<x-seller-verification.layout :seller="$seller">
<h2>Application summary</h2><p>Current status: <strong>{{ str_replace('_',' ', $seller->verification_status) }}</strong></p>
<dl style="line-height:2"><dt>Seller / Shop</dt><dd>{{ $seller->seller_name }} — {{ $seller->shop_name }}</dd><dt>Email / Mobile</dt><dd>{{ $seller->email }} — {{ $seller->mobile_number }}</dd><dt>Business</dt><dd>{{ $seller->business_type }} · {{ $seller->shop_address }}, {{ $seller->city }}, {{ $seller->state }} {{ $seller->pincode }}</dd><dt>GST</dt><dd>{{ $seller->gst_number ?: 'Not provided' }}</dd><dt>PAN / Udyam</dt><dd>{{ $seller->pan_number ? 'Provided' : 'Not provided' }} / {{ $seller->udyam_number ? 'Provided' : 'Not provided' }}</dd><dt>Bank account</dt><dd>{{ $seller->bank_account_number ? str_repeat('*', max(0, strlen($seller->bank_account_number)-4)).substr($seller->bank_account_number,-4) : 'Not provided' }}</dd><dt>Documents</dt><dd>Business Certificate: {{ $seller->business_certificate_path ? 'Uploaded' : 'Pending' }}; Aadhaar: {{ $seller->aadhaar_document_path ? 'Uploaded' : 'Pending' }}</dd><dt>Submitted</dt><dd>{{ optional($seller->verification_submitted_at)->toDayDateTimeString() ?: 'Not submitted' }}</dd></dl>
</x-seller-verification.layout>
